import React from "react";
import { random } from "remotion";
import { palette } from "../theme/palette";
import { Flower, Leaf, type FlowerTone } from "./Florals";
import { qPt, type Pt } from "./WeddingDayKit";

/*
 * Wedding-day decor: hanging brass lanterns, thalis, flower heaps and flowers threaded along
 * curves (garlands whose control points animate). Drawn in scene (SVG user) space.
 */

/** Brass hanging lantern with glowing panes. (x, y) = hanging point; `swing` in degrees. */
export const Lantern: React.FC<{ x: number; y: number; len: number; s?: number; swing?: number; glow?: number; body?: string; id: string }> = ({
  x,
  y,
  len,
  s = 1,
  swing = 0,
  glow = 1,
  body = palette.brass,
  id,
}) => (
  <g transform={`translate(${x} ${y}) rotate(${swing})`}>
    <defs>
      <radialGradient id={`${id}-g`}>
        <stop offset="0" stopColor="#FFE3A0" stopOpacity={0.7} />
        <stop offset="0.45" stopColor="#FFC870" stopOpacity={0.25} />
        <stop offset="1" stopColor="#FFC870" stopOpacity={0} />
      </radialGradient>
    </defs>
    <path d={`M0 0 L0 ${len}`} stroke={palette.goldDeep} strokeWidth={1.4} />
    <g transform={`translate(0 ${len}) scale(${s})`}>
      <circle cx={0} cy={64} r={110} fill={`url(#${id}-g)`} opacity={glow} />
      <circle cx={0} cy={2} r={5} fill="none" stroke={body} strokeWidth={2} />
      <path d="M-10 8 L10 8 L26 30 L-26 30 Z" fill={body} />
      <path d="M-26 30 C-26 18 26 18 26 30" fill="url(#foil)" />
      <rect x={-30} y={30} width={60} height={6} fill="url(#foil-v)" />
      <path d="M-26 36 L26 36 L30 92 L-30 92 Z" fill="#FFE4A8" opacity={0.55 + 0.45 * glow} />
      <path d="M-13 36 L-15 92 M0 36 L0 92 M13 36 L15 92" stroke={body} strokeWidth={3} />
      <path d="M-26 36 L-30 92 M26 36 L30 92" stroke={body} strokeWidth={4} />
      <path d="M-22 60 C-14 52 -4 52 0 60 C4 52 14 52 22 60" fill="none" stroke={body} strokeWidth={1.6} />
      <rect x={-34} y={92} width={68} height={7} fill="url(#foil-v)" />
      <path d="M-24 99 L24 99 L8 118 L-8 118 Z" fill={body} />
      <circle cx={0} cy={124} r={5} fill="url(#foil)" />
      <path d="M0 129 L0 150" stroke={palette.maroon} strokeWidth={3} />
      <path d="M-5 150 L5 150 L3 172 L-3 172 Z" fill={palette.maroon} />
    </g>
  </g>
);

/** Brass thali seen at an angle: rim, katoris, optionally a mound of petals. */
export const Thali: React.FC<{ x: number; y: number; r: number; tilt?: number; petals?: boolean; katoris?: boolean }> = ({
  x,
  y,
  r,
  tilt = 0.38,
  petals,
  katoris = true,
}) => (
  <g transform={`translate(${x} ${y})`}>
    <ellipse cx={0} cy={r * tilt * 0.35} rx={r * 1.02} ry={r * tilt * 1.02} fill={palette.ink} opacity={0.14} />
    <ellipse cx={0} cy={0} rx={r} ry={r * tilt} fill="#C99A48" />
    <ellipse cx={0} cy={-r * tilt * 0.06} rx={r * 0.9} ry={r * tilt * 0.86} fill="#E3C27A" />
    <ellipse cx={0} cy={-r * tilt * 0.06} rx={r * 0.9} ry={r * tilt * 0.86} fill="none" stroke={palette.goldDeep} strokeWidth={1} opacity={0.5} />
    {katoris
      ? [-0.5, 0, 0.5].map((k, i) => (
          <g key={k} transform={`translate(${k * r * 0.95} ${-r * tilt * (i === 1 ? 0.45 : 0.2)})`}>
            <ellipse cx={0} cy={0} rx={r * 0.2} ry={r * 0.2 * tilt * 1.3} fill="#B8883E" />
            <ellipse cx={0} cy={-1} rx={r * 0.16} ry={r * 0.16 * tilt * 1.2} fill={[palette.marigoldDeep, "#F2E6CC", palette.greenLight][i]} />
          </g>
        ))
      : null}
    {petals ? (
      <g>
        {new Array(14).fill(0).map((_, i) => {
          const a = i * 2.4;
          const rr = (i / 14) * r * 0.6;
          return (
            <path
              key={i}
              d="M0 0 C4 -5 10 -5 12 0 C10 4 4 5 0 0 Z"
              transform={`translate(${Math.cos(a) * rr} ${Math.sin(a) * rr * tilt - r * tilt * 0.2}) rotate(${i * 47}) scale(${r / 60})`}
              fill={i % 3 === 0 ? palette.marigold : i % 3 === 1 ? palette.rose : palette.roseLight}
            />
          );
        })}
      </g>
    ) : null}
  </g>
);

/** A loose heap of flowers (tray contents, stage bases, arch feet). */
export const FlowerHeap: React.FC<{ x: number; y: number; w: number; r?: number; seed: string; tones?: FlowerTone[]; rows?: number }> = ({
  x,
  y,
  w,
  r = 12,
  seed,
  tones = ["orange", "rose", "yellow", "ivory"],
  rows = 1,
}) => {
  const n = Math.max(3, Math.round(w / (r * 1.3)));
  const items: React.ReactNode[] = [];
  for (let row = 0; row < rows; row++) {
    for (let i = 0; i < n - row; i++) {
      const t = (i + row * 0.5) / (n - 1);
      const h = Math.sin(t * Math.PI) * r * 1.2 + row * r * 1.1;
      const fx = x - w / 2 + t * w + (random(`${seed}x${row}-${i}`) - 0.5) * r * 0.6;
      const fy = y - h - (i % 2) * r * 0.45;
      if (i % 2 === 0)
        items.push(<Leaf key={`l${row}-${i}`} x={fx} y={fy + r * 0.4} rot={random(`${seed}l${row}-${i}`) * 360} s={r / 10} color={i % 4 ? palette.green : palette.greenDeep} />);
      items.push(
        <Flower
          key={`f${row}-${i}`}
          x={fx}
          y={fy}
          r={r * (0.85 + random(`${seed}r${row}-${i}`) * 0.3)}
          tone={tones[(i + row) % tones.length]}
          rot={random(`${seed}o${row}-${i}`) * 90}
        />,
      );
    }
  }
  return <g>{items}</g>;
};

/** Flowers threaded along a quadratic curve (garland pieces whose control points animate). */
export const FlowerCurve: React.FC<{ a: Pt; c: Pt; b: Pt; r: number; seed: string; tones?: FlowerTone[]; step?: number; leaves?: boolean }> = ({
  a,
  c,
  b,
  r,
  seed,
  tones = ["orange", "orange", "yellow", "rose"],
  step = 1.55,
  leaves = true,
}) => {
  const len = Math.hypot(c[0] - a[0], c[1] - a[1]) + Math.hypot(b[0] - c[0], b[1] - c[1]);
  const n = Math.max(2, Math.floor(len / (r * step)));
  const pts = new Array(n + 1).fill(0).map((_, i) => qPt(a, c, b, i / n));
  return (
    <g>
      {leaves
        ? pts.map((p, i) =>
            i % 3 === 1 ? <Leaf key={`l${i}`} x={p[0]} y={p[1]} rot={random(`${seed}l${i}`) * 360} s={r / 9} color={i % 2 ? palette.green : palette.greenDeep} /> : null,
          )
        : null}
      {pts.map((p, i) => (
        <Flower key={i} x={p[0]} y={p[1]} r={r} tone={tones[i % tones.length]} rot={random(`${seed}${i}`) * 90} />
      ))}
    </g>
  );
};
